  1	/**
  2	 * ui.Table and ui.TableRow components.
  3	 *
  4	 * spec/ui/vocabulary.md:
  5	 *   - ui.Table: many rows, real columns, comparison across rows.
  6	 *   - ui.TableRow: one row of a Table.
  7	 *
  8	 * Answering the four states: loading, ready, empty, error.
  9	 * Pure descriptions: props in, Node out. Zero DOM manipulation.
 10	 */
 11	
 12	import { ActionButton } from '../composites/actionButton.js';
 13	import { element, read, text, when } from '@flybyme/mesh-web';
 14	import type { Node } from '@flybyme/mesh-web';
 15	import {
 16	    defineComponent, UI_TABLE, UI_TABLE_ROW,
 17	    type Component, type EntityListStatus, type TableProps, type TableRowProps,
 18	} from '../contract.js';
 19	
 20	export const Table: Component<TableProps> = defineComponent<TableProps>(
 21	    UI_TABLE,
 22	    'Many rows, real columns, comparison across rows.',
 23	    (props) => {
 24	        const currentStatus = (): EntityListStatus => read(props.status) ?? 'ready';
 25	
 26	        const headersList = (): readonly string[] => read(props.headers) ?? [];
 27	        const hasHeaders = (): boolean => headersList().length > 0;
 28	
 29	        const headerNode = (): Node => element('Row', {
 30	            props: {
 31	                class: () => {
 32	                    const extra = read(props.headerClass);
 33	                    return `ui-table-header${extra ? ` ${extra}` : ''}`;
 34	                },
 35	                role: 'row',
 36	            },
 37	            children: headersList().map((headerText) => element('Text', {
 38	                props: { class: 'ui-table-header-cell', role: 'columnheader' },
 39	                children: [text(headerText)],
 40	            })),
 41	        });
 42	
 43	        const loadingNode = (): Node => element('Row', {
 44	            props: { class: 'ui-table-loading', role: 'status' },
 45	            children: [text(() => read(props.loadingMessage) ?? 'Loading…')],
 46	        });
 47	
 48	        const errorNode = (): Node => {
 49	            const err = read(props.errorMessage);
 50	            if (typeof err === 'object' && err !== null && 'refused' in err) {
 51	                return element('Row', {
 52	                    props: { class: 'ui-table-refused', role: 'status' },
 53	                    children: [
 54	                        element('Text', {
 55	                            props: { class: 'ui-table-refused-message' },
 56	                            children: [text(err.refused)],
 57	                        }),
 58	                    ],
 59	                });
 60	            }
 61	            return element('Row', {
 62	                props: { class: 'ui-table-error', role: 'alert' },
 63	                children: [text(typeof err === 'string' ? err : 'Failed to load')],
 64	            });
 65	        };
 66	
 67	        const emptyNode = (): Node => element('Row', {
 68	            props: { class: 'ui-table-empty', role: 'status' },
 69	            children: [text(() => read(props.emptyMessage) ?? 'No records found.')],
 70	        });
 71	
 72	        const rowsNode = (): Node => element('Stack', {
 73	            props: {
 74	                class: () => {
 75	                    const extra = read(props.rowsClass);
 76	                    return `ui-table-rows${extra ? ` ${extra}` : ''}`;
 77	                },
 78	                role: 'rowgroup',
 79	            },
 80	            children: [
 81	                ...(props.children ?? []),
 82	                ...(props.action ? [
 83	                    element('Text', {
 84	                        props: { class: 'ui-table-cell ui-table-action-cell', role: 'cell' },
 85	                        children: [ActionButton(props.action)]
 86	                    })
 87	                ] : [])
 88	            ],
 89	        });
 90	
 91	        const contentBranch = (): Node => when(
 92	            () => currentStatus() === 'loading',
 93	            loadingNode,
 94	            () => when(
 95	                () => currentStatus() === 'error',
 96	                errorNode,
 97	                () => when(
 98	                    () => currentStatus() === 'empty',
 99	                    emptyNode,
100	                    rowsNode,
101	                ),
102	            ),
103	        );
104	
105	        return element('Stack', {
106	            props: {
107	                class: () => {
108	                    const extra = read(props.class);
109	                    const s = currentStatus();
110	                    return `ui-table ui-table-${s}${extra ? ` ${extra}` : ''}`;
111	                },
112	                'data-status': () => currentStatus(),
113	                role: 'table',
114	            },
115	            children: [
116	                when(hasHeaders, headerNode),
117	                contentBranch(),
118	            ],
119	        });
120	    },
121	);
122	
123	export const TableRow: Component<TableRowProps> = defineComponent<TableRowProps>(
124	    UI_TABLE_ROW,
125	    'One row of a Table.',
126	    (props) => {
127	        const isSelected = (): boolean => Boolean(read(props.selected));
128	
129	        return element('Row', {
130	            props: {
131	                class: () => {
132	                    const extra = read(props.class);
133	                    const sel = isSelected();
134	                    return `ui-table-row${sel ? ' selected' : ''}${extra ? ` ${extra}` : ''}`;
135	                },
136	                role: 'row',
137	                'data-selected': () => String(isSelected()),
138	                'aria-selected': () => String(isSelected()),
139	            },
140	            ...(props.intents ? { intents: props.intents } : {}),
141	            ...(props.key !== undefined ? { key: props.key } : {}),
142	            children: props.children ?? [],
143	        });
144	    },
145	);

